<template>
  <div class="tc-card">
    <div class="tc-summary"><button v-for="state in statuses" :key="state.value" :class="{ selected: filters.status === state.value }" @click="filters.status = state.value">{{ state.label }} <strong>{{ list?.counters[state.count] ?? '—' }}</strong></button><span>{{ management ? '全部成员的任务 · 只读查看' : '本业务全部成员的任务' }}</span></div>
    <div class="tc-filters"><label>任务名称<ElInput v-model="filters.search" clearable placeholder="搜索任务名称" aria-label="搜索任务名称" maxlength="200" /></label><label v-if="management">所属业务<ElSelect v-model="filters.workspace" clearable placeholder="全部业务" aria-label="所属业务筛选"><ElOption v-for="item in workspaces" :key="item.key" :label="item.title" :value="item.key" /></ElSelect></label><label v-if="management">创建人<ElSelect v-model="filters.ownerId" clearable filterable placeholder="全部成员" aria-label="创建人筛选"><ElOption v-for="member in list?.members || []" :key="member.id" :label="member.name" :value="member.id" /></ElSelect></label><ElButton @click="$emit('reset')">重置筛选</ElButton></div>
    <div class="tc-list-note"><span>{{ workspace ? `${workspace.group} / ${workspace.title}` : '全部成员 · 全部业务任务' }}</span><span>共 {{ list?.total ?? '—' }} 个任务</span></div>
    <ElTable v-loading="loading" :data="list?.items || []" class="tc-table" row-key="id"><ElTableColumn label="任务名称" min-width="290"><template #default="{ row }"><button class="tc-task-name" @click="$emit('enter', row)">{{ row.name }}</button><small class="tc-sub">{{ row.conversationCount }} 个方案会话<span v-if="row.activeConversationCount"> · {{ row.activeConversationCount }} 个处理中</span></small><small v-if="row.deletionStatus" class="tc-sub">{{ row.deletionStatus === 'deleting' ? '正在清理任务与文件' : row.deletionError || '删除失败，可重试' }}</small></template></ElTableColumn><ElTableColumn label="所属业务" min-width="220"><template #default="{ row }">{{ workspaces.find(item => item.key === row.workspace)?.title }}</template></ElTableColumn><ElTableColumn label="创建人" width="125"><template #default="{ row }"><span class="tc-person">{{ row.ownerName }}</span></template></ElTableColumn><ElTableColumn label="任务状态" width="120"><template #default="{ row }"><ElTag :type="row.completed ? 'success' : 'primary'" size="small">{{ row.completed ? '已完成' : '进行中' }}</ElTag></template></ElTableColumn><ElTableColumn label="最近更新（北京时间）" width="190"><template #default="{ row }">{{ formatBeijingTime(row.updatedAt) }}</template></ElTableColumn><ElTableColumn label="操作" width="180" fixed="right"><template #default="{ row }"><ElButton link type="primary" @click="$emit('enter', row)">{{ management || row.ownerId !== actor ? '只读查看' : '进入任务' }}</ElButton><ElDropdown v-if="!management && row.ownerId === actor" trigger="click" :disabled="busy" @command="(command: string) => $emit('action', command, row)"><ElButton link :disabled="busy" aria-label="更多任务操作">更多</ElButton><template #dropdown><ElDropdownMenu><ElDropdownItem command="rename" :disabled="row.completed || !!row.deletionStatus">重命名</ElDropdownItem><ElDropdownItem command="complete" :disabled="!!row.activeConversationCount || !!row.deletionStatus">{{ row.completed ? '重新打开' : '标记完成' }}</ElDropdownItem><ElDropdownItem command="delete" :disabled="!!row.activeConversationCount || row.deletionStatus === 'deleting'" divided>{{ row.deletionStatus === 'delete_failed' ? '重试删除任务' : '删除任务' }}</ElDropdownItem></ElDropdownMenu></template></ElDropdown></template></ElTableColumn><template #empty><div class="tc-empty"><ElIcon><FolderOpened /></ElIcon><strong>{{ filters.search || filters.workspace || filters.ownerId || filters.status ? '没有符合条件的任务' : '还没有设计任务' }}</strong><p>{{ management ? '暂无符合条件的任务，可调整筛选条件。' : '点击“新建任务”，为本次设计填写名称。' }}</p><ElButton v-if="!management" type="primary" :disabled="busy" @click="$emit('create')">新建任务</ElButton></div></template></ElTable>
    <div class="tc-pagination"><span>任务下的每个方案会话拥有独立上下文</span><ElPagination v-model:current-page="filters.page" :total="list?.total || 0" :page-size="filters.pageSize" layout="prev, pager, next" /></div>
  </div>
</template>
<script setup lang="ts">
import { FolderOpened } from '@element-plus/icons-vue'
import { domesticWorkspaces as workspaces } from '@/api/hengxin/domestic-workspaces'
import type { DomesticTask, TaskFilters, TaskList } from '@/api/hengxin/domestic-tasks'
import { formatBeijingTime } from '@/utils/beijing-time'
defineProps<{ filters: TaskFilters; list?: TaskList; workspace?: typeof workspaces[number]; management: boolean; actor: string; loading: boolean; busy: boolean }>()
defineEmits<{ reset: []; enter: [task: DomesticTask]; action: [command: string, task: DomesticTask]; create: [] }>()
const statuses = [{ value: '', label: '全部任务', count: 'total' }, { value: 'active', label: '进行中', count: 'active' }, { value: 'completed', label: '已完成', count: 'completed' }] as const
</script>
